export const hexagrams=rows.split('\n').map((r,i)=>{const [name,up,low,meaning,story]=r.split('|');return {id:i+1,name,up:trigrams.find(t=>t.id===up),low:trigrams.find(t=>t.id===low),meaning,story};});
export const bits=h=>h.low.code+h.up.code;
export const byBits=b=>hexagrams.find(h=>bits(h)===b);
